window.generateRandomMixedStudy = function() {
  var s1 = window.STUDY_DATA_LIST["1"];
  var s2 = window.STUDY_DATA_LIST["2"];
  if (!s1 || !s2) return window.STUDY_DATA_LIST["3"];

  function sample(arr, n) {
    var sh = arr.slice();
    for (var i = sh.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = sh[i]; sh[i] = sh[j]; sh[j] = tmp;
    }
    return sh.slice(0, n);
  }
  function shuffle(arr) {
    for (var i = arr.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
    }
    return arr;
  }
  function clone(obj) {
    return JSON.parse(JSON.stringify(obj));
  }
  function chunkArray(arr, size) {
    var res = [];
    for (var i = 0; i < arr.length; i += size) {
      res.push(arr.slice(i, i + size));
    }
    return res;
  }

  var p1_s1 = s1.filter(function(x) { return x.part === 1; });
  var p1_s2 = s2.filter(function(x) { return x.part === 1; });
  var p1 = shuffle(sample(p1_s1, 3).concat(sample(p1_s2, 3)));

  var p2_s1 = s1.filter(function(x) { return x.part === 2; });
  var p2_s2 = s2.filter(function(x) { return x.part === 2; });
  var n1 = Math.random() < 0.5 ? 13 : 12;
  var p2 = shuffle(sample(p2_s1, n1).concat(sample(p2_s2, 25 - n1)));

  var p3_s1 = chunkArray(s1.filter(function(x) { return x.part === 3; }), 3);
  var p3_s2 = chunkArray(s2.filter(function(x) { return x.part === 3; }), 3);
  var g1 = Math.random() < 0.5 ? 7 : 6;
  var p3Chunks = shuffle(sample(p3_s1, g1).concat(sample(p3_s2, 13 - g1)));
  var p3 = [].concat.apply([], p3Chunks);

  var p4_s1 = chunkArray(s1.filter(function(x) { return x.part === 4; }), 3);
  var p4_s2 = chunkArray(s2.filter(function(x) { return x.part === 4; }), 3);
  var p4Chunks = shuffle(sample(p4_s1, 5).concat(sample(p4_s2, 5)));
  var p4 = [].concat.apply([], p4Chunks);

  var p5_s1 = s1.filter(function(x) { return x.part === 5; });
  var p5_s2 = s2.filter(function(x) { return x.part === 5; });
  var p5 = shuffle(sample(p5_s1, 15).concat(sample(p5_s2, 15)));

  var p6_s1 = chunkArray(s1.filter(function(x) { return x.part === 6; }), 4);
  var p6_s2 = chunkArray(s2.filter(function(x) { return x.part === 6; }), 4);
  var p6Chunks = shuffle(sample(p6_s1, 2).concat(sample(p6_s2, 2)));
  var p6 = [].concat.apply([], p6Chunks);

  function groupP7(items, clusterSizes) {
    var res = [];
    var idx = 0;
    clusterSizes.forEach(function(size) {
      res.push(items.slice(idx, idx + size));
      idx += size;
    });
    return res;
  }
  var t1_sizes = [2, 3, 3, 3, 3, 4, 3, 2, 4, 3, 5, 5, 4, 5, 5];
  var t2_sizes = [3, 2, 4, 3, 3, 3, 3, 3, 4, 2, 5, 5, 5, 5, 4];
  var p7_s1_groups = groupP7(s1.filter(function(x) { return x.part === 7; }), t1_sizes);
  var p7_s2_groups = groupP7(s2.filter(function(x) { return x.part === 7; }), t2_sizes);

  var s1_single = p7_s1_groups.slice(0, 10);
  var s2_single = p7_s2_groups.slice(0, 10);
  var p7SingleChunks = [];
  for (var iter = 0; iter < 100; iter++) {
    var sub1 = sample(s1_single, 5);
    var sub2 = sample(s2_single, 5);
    var tot = sub1.concat(sub2).reduce(function(acc, g) { return acc + g.length; }, 0);
    if (tot === 30) {
      p7SingleChunks = shuffle(sub1.concat(sub2));
      break;
    }
  }
  if (p7SingleChunks.length === 0) p7SingleChunks = s1_single;

  var m1_multi = p7_s1_groups.slice(10);
  var m2_multi = p7_s2_groups.slice(10);
  var p7MultiChunks = [];
  for (var iter = 0; iter < 100; iter++) {
    var take1 = Math.random() < 0.5 ? 2 : 3;
    var sub1 = sample(m1_multi, take1);
    var sub2 = sample(m2_multi, 5 - take1);
    var tot = sub1.concat(sub2).reduce(function(acc, g) { return acc + g.length; }, 0);
    if (tot === 24) {
      p7MultiChunks = shuffle(sub1.concat(sub2));
      break;
    }
  }
  if (p7MultiChunks.length === 0) p7MultiChunks = m1_multi;

  var p7 = [].concat.apply([], p7SingleChunks.concat(p7MultiChunks));
  var allItems = [].concat(p1, p2, p3, p4, p5, p6, p7);

  var curQ = 1;
  return allItems.map(function(item) {
    var it = clone(item);
    it.qNum = curQ;
    if (it.part === 1) {
      it.cleanTitle = "Question " + curQ + ": Listen and choose the statement that best describes the picture.";
    } else if (it.part === 2) {
      var rawQ = (it.cleanTitle || '').replace(/^Câu \d+:\s*"?/, '').replace(/"?$/, '');
      it.cleanTitle = 'Câu ' + curQ + ': "' + rawQ + '"';
    } else if (it.part === 6) {
      it.cleanTitle = 'Câu ' + curQ + ': Chọn từ/cụm từ đúng nhất điền vào vị trí (' + curQ + ')';
    } else if (it.cleanTitle) {
      it.cleanTitle = curQ + '. ' + it.cleanTitle.replace(/^\d+\.\s*/, '');
    }
    curQ++;
    return it;
  });
};

(function() {
  var selected = 1;
  try {
    var saved = localStorage.getItem('TOEIC_SELECTED_STUDY_ID');
    if (saved && window.STUDY_DATA_LIST[saved]) {
      selected = parseInt(saved, 10);
    }
  } catch(e) {}
  window.CURRENT_STUDY_ID = selected;
  if (selected === 3) {
    window.STUDY_DATA_LIST["3"] = window.generateRandomMixedStudy();
  }
  window.STUDY_DATA = window.STUDY_DATA_LIST[selected] || window.STUDY_DATA_LIST[1];
})();
